import {quizQuestion,TIERS} from './angle-model.js?v=18';
export {TIERS};
export const DEFAULT_COUNTS={1:4,2:4,3:4,4:4,5:4};
export const questionLimit=(tier,space='standard')=>space==='spacious'?2:4;
export function seededRandom(seed){let h=2166136261;for(const c of String(seed)){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return()=>{h+=0x6D2B79F5;let t=h;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;};}
export function validateConfig(config){const errors=[];if(!['straight','circle'].includes(config.mode))errors.push('Choose an angle topic.');const tiers=config.tiers??[];if(!tiers.length)errors.push('Select at least one tier.');if(new Set(tiers).size!==tiers.length||tiers.some(t=>!Number.isInteger(t)||t<1||t>5))errors.push('Choose tiers 1 to 5.');if(!['standard','spacious'].includes(config.space))errors.push('Choose a working-space preference.');for(const t of tiers){const n=config.counts?.[t],max=questionLimit(t,config.space);if(!Number.isInteger(n)||n<1||n>max)errors.push(`Tier ${t}: choose 1–${max} questions for this working-space setting.`);}if(typeof config.title!=='string'||config.title.length>55)errors.push('Keep the worksheet title within 55 characters.');if(typeof config.seed!=='string'||!config.seed.trim()||config.seed.length>40)errors.push('Enter a seed of 1–40 characters.');return errors;}
export function validQuestion(q){return q.terms.length===q.values.length&&q.values.every((v,i)=>Number.isFinite(v)&&v>0&&Math.abs(v-(q.terms[i].a*q.answer+q.terms[i].b))<1e-8)&&Math.abs(q.values.reduce((s,v)=>s+v,0)-q.total)<1e-8&&q.terms.reduce((s,t)=>s+t.a,0)>0;}
export function solution(q,language='en'){const bm=language==='bm',term=t=>t.a?`${t.a===1?'':t.a}${q.symbol}${t.b?` ${t.b<0?'−':'+'} ${Math.abs(t.b)}`:''}`:String(t.b),expression=q.terms.map(t=>t.a&&t.b?`(${term(t)})`:term(t)).join(' + '),A=q.terms.reduce((s,t)=>s+t.a,0),B=q.terms.reduce((s,t)=>s+t.b,0),ax=`${A===1?'':A}${q.symbol}`;
 const steps=[`${expression} = ${q.total}°`,`${ax} + ${B} = ${q.total}`,`${ax} = ${q.total} − ${B} = ${q.total-B}`];if(A!==1)steps.push(`${q.symbol} = ${q.total-B} ÷ ${A}`);steps.push(`${q.symbol} = ${q.answer}°`);
 return {rule:q.total===180?(bm?'Jumlah sudut pada garis lurus ialah 180°.':'Angles on a straight line add up to 180°.'):bm?'Jumlah sudut di sekeliling titik ialah 360°.':'Angles around a point add up to 360°.',steps,check:`${bm?'Semakan':'Check'}: ${q.values.join(' + ')} = ${q.total}°`,answer:`${q.symbol} = ${q.answer}°`};}
export function generateWorksheet(config){const errors=validateConfig(config);if(errors.length)throw Error(errors.join('\n'));const rng=seededRandom(config.seed),pages=[];let number=0;for(const tier of [...config.tiers].sort((a,b)=>a-b)){const seen=new Set(),answers=new Set(),next=(band=null)=>{for(let i=0;i<2000;i++){const q=quizQuestion(config.mode,tier,rng),signature=JSON.stringify([...q.values].sort((a,b)=>a-b));const min=q.algebra?12:15,max=q.algebra?Math.floor((q.total-q.terms.filter(t=>t.a).reduce((n,t)=>n+t.b,0)-35)/q.terms.reduce((n,t)=>n+t.a,0)):q.total-(q.terms.length-1)*15;
const range=Math.min(3,Math.floor((q.answer-min)/(max-min+1)*4));
if(validQuestion(q)&&!seen.has(signature)&&!answers.has(q.answer)&&(band===null||range===band)){seen.add(signature);answers.add(q.answer);return q;}}throw Error('Unable to produce distinct valid questions. Try a different seed.');};pages.push({tier,example:next(),questions:Array.from({length:config.counts[tier]},(_,i)=>({number:++number,question:next(i%4)}))});}return {version:2,mode:config.mode,language:config.language==='bm'?'bm':'en',title:config.title.trim(),seed:config.seed,space:config.space,pages,worksheetPages:pages.length,answerPages:pages.length};}
export function pageLayout(tier,count){const columns=tier<=2||count===4?2:1,rows=Math.ceil(count/columns),gap=8,width=(182-gap*(columns-1))/columns,height=136/rows;return Array.from({length:count},(_,i)=>({x:14+(i%columns)*(width+gap),y:140+Math.floor(i/columns)*height,width,height}));}
